# FDN Kalastria Highborn: "Whenever this creature or another Vampire you control dies, you may pay
# {B}. If you do, target player loses 2 life and you gain 2 life."
# Event: M21 Thieves' Guild Enforcer's verified "this creature or another Rogue you control" subject,
# a Vampire, on a CreatureDiesEvent; effect: M21 Ghostly Pilferer's verified "you may pay {2}. If you
# do, ..." at {B}, then Spirit of Malevolence's "loses N life and you gain N life" with Sublime
# Epiphany's "target player" (TARGET_PLAYER, chosen as the trigger goes on the stack).
trigger = TriggeredAbility(
    event=CreatureDiesEvent(
        filter=FOr(
            children=(
                FAnd(
                    children=(
                        FAtom(pred=FAtomPred.CONTROLLER_IS, who=ControllerRef.YOU),
                        FAtom(pred=FAtomPred.SUBTYPE_EQ, string_value='Vampire'),
                        FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                        FNot(inner=FAtom(pred=FAtomPred.IS_SOURCE)),
                    ),
                ),
                FAtom(pred=FAtomPred.IS_SOURCE),
            ),
        ),
    ),
    condition=None,
    effect=Seq(
        steps=(
            OptionalEffect(
                inner=A(Verb.PAY, {
                    'cost': Cost(parts=(CostManaColor(color='B', amount=QConst(value=1)),)),
                }),
            ),
            Conditional(
                pred=FAtom(pred=FAtomPred.MAY_DONE),
                then_effect=Seq(
                    steps=(
                        A(Verb.LOSE_LIFE, {
                            'amount': QConst(value=2),
                            'controller': ControllerRef.TARGET_PLAYER,
                        }),
                        A(Verb.GAIN_LIFE, {'amount': QConst(value=2), 'controller': ControllerRef.YOU}),
                    ),
                ),
            ),
        ),
    ),
)
abilities = [trigger, *compiled]
